      p_mimes_allowed  => '',
      p_comments       => NULL,
      p_source         => 
'DECLARE
    v_count         number;
    v_licencia      varchar2(100) := generar_licencia();
    v_capacidad_emp number;
    v_emp_id        number;
    v_usado_emp     number;
BEGIN
    -- Comprueba si el usuario existe
    select count(''x'') into v_count from clientes where upper(cli_email) = upper(:email) and toolkit.desencriptar(cli_clave,''AIO987654'') = :clave;

    IF v_count > 0 THEN    

        -- Sacar datos de la empresa
        IF :empresa is null THEN
            select emp_id, emp_capacidad into v_emp_id, v_capacidad_emp
            from clientes, empresas
            where cli_id = emp_cliente
                and upper(cli_email) = upper(:email) and toolkit.desencriptar(cli_clave,''AIO987654'') = :clave
                and rownum = 1;
        ELSE    
            v_emp_id := :empresa;
            select emp_capacidad into v_capacidad_emp
            from empresas
            where emp_id = v_emp_id;
        END IF;

        -- Comprobar capacidad de empresa
        select nvl(sum(nvl(equ_usado,0)),0) + nvl(:usado,0) into v_usado_emp
        from equipos
        where equ_emp = v_emp_id;

        IF nvl(:usado,0) <= nvl(:capacidad,v_capacidad_emp) and v_usado_emp <= v_capacidad_emp THEN
            -- Crear equipo
            :licencia := v_licencia;        
            INSERT INTO EQUIPOS (EQU_ID, EQU_EMP, EQU_NOMBRE, EQU_IP, EQU_UBICACION, EQU_ACTIVO, EQU_ESTADO, EQU_LICENCIA, EQU_USADO, EQU_CAPACIDAD
            ) VALUES (
                EQUIPOS_SEQ.nextval,     -- EQU_ID
                v_emp_id,                -- EQU_EMP
                nvl(:nombre,''MI PC''),    -- EQU_NOMBRE
                :ip,                     -- EQU_IP
                :ubicacion,              -- EQU_UBICACION
                :cargo,                  -- EQU_CARGO
                :descripcion,            -- EQU_DESCRIPCION
                ''S'',                     -- EQU_ACTIVO
                nvl(:estado,''CORRECTO''), -- EQU_ESTADO
                v_licencia,              -- EQU_LICENCIA
                nvl(:usado,0),           -- EQU_USADO
                nvl(:capacidad,100)      -- EQU_CAPACIDAD
            );
        ELSE
            :error := ''Capacidad superada (''||v_usado_emp||'' / ''||v_capacidad_emp||'' GB)''; 
        END IF;
    ELSE
        :error := ''Usuario no válido'';
    END IF;
END;');

