  ORDS.DEFINE_HANDLER(
      p_module_name    => 'api',
      p_pattern        => 'equipos/actualizar',
      p_method         => 'PUT',
      p_source_type    => 'plsql/block',
      p_mimes_allowed  => '',
      p_comments       => NULL,
      p_source         => 
'DECLARE
    v_capacidad     number;
    v_capacidad_emp number;
    v_emp_id        number;
    v_usado_emp     number;
BEGIN
    -- Comprobar capacidad de equipo
    select nvl(equ_capacidad,emp_capacidad), emp_capacidad, emp_id into v_capacidad, v_capacidad_emp, v_emp_id
    from equipos, empresas
    where equ_emp = emp_id
        and equ_licencia = :licencia;
    
    -- Comprobar capacidad de empresa
    select nvl(sum(nvl(equ_usado,0)),0) + nvl(:usado,0) into v_usado_emp
    from equipos
    where equ_emp = v_emp_id;

    IF nvl(:usado,0) <= v_capacidad AND v_usado_emp <= v_capacidad_emp THEN
        update equipos
        set
            EQU_NOMBRE      = NVL(:nombre, EQU_NOMBRE),
            EQU_IP          = NVL(:ip, EQU_IP),
            EQU_UBICACION   = NVL(:ubicacion, EQU_UBICACION),
            EQU_CARGO       = NVL(:cargo, EQU_CARGO),
            EQU_DESCRIPCION = NVL(:descripcion, EQU_DESCRIPCION),
            EQU_ACTIVO      = NVL(:activo, EQU_ACTIVO),
            EQU_ESTADO      = NVL(:estado, EQU_ESTADO),
            EQU_USADO       = NVL(:usado, EQU_USADO),
            EQU_CAPACIDAD   = NVL(:capacidad, EQU_CAPACIDAD)
        where equ_licencia = :licencia;
    ELSE
        :error := ''Supera la capacidad máxima (''||v_usado_emp||'' / ''||v_capacidad_emp||'' GB)'';
    END IF;
    
END;');

